        final r = _map(rules[i]);
        expect(cms.normalizeManagedSettings(<String, Object?>{
          'permissions': <String, Object?>{leaf: <Object?>[]}}), _map(r['empty']));
        expect(cms.normalizeManagedSettings(<String, Object?>{
          'permissions': <String, Object?>{leaf: <Object?>['Shell']}}), _map(r['rules']));
        expect(cms.MANAGED_SETTINGS_CONTROL_DEFINITIONS[key]!.type,
