        'telemetry.enabled': IManagedSettingPolicyDefinition('boolean'),
        'telemetry.capture.identity': IManagedSettingPolicyDefinition('boolean'),
        'telemetry.resourceAttributes': IManagedSettingPolicyDefinition('string'),
      };
      Map<String, Object?> norm(Object? value) => cms.normalizeManagedSettings(
          <String, Object?>{'telemetry': <String, Object?>{
            'filePath': value,
            'enabled': false,
            'capture': <String, Object?>{'identity': false},
            'resourceAttributes': <String, Object?>{'service.namespace': 'acme'},
          }});
      Map<String, Object?> proj(Object? value, [List<String>? w]) =>
          cms.projectManagedSettings(norm(value), decls, w == null ? null : w.add);
      expect(proj('/var/log/copilot.jsonl'), _map(e['string']));
      expect(proj(null), _map(e['null']));
      expect(norm(<String, Object?>{'path': '/var/log/copilot.jsonl'}), _map(e['object']));
      expect(proj(<String, Object?>{'path': '/var/log/copilot.jsonl'}), _map(e['objectProjected']));
      expect(proj(<Object?>['/var/log/copilot.jsonl']), _map(e['array']));
      final nw = <String>[];
      expect(proj(1, nw), _map(e['number']));
      expect(nw, e['numberWarnings']);
      expect(cms.projectManagedSettings(
          cms.normalizeManagedSettings(<String, Object?>{
            'telemetry': <String, Object?>{'enabled': false}}), decls),
          _map(e['missing']));
