  group('batch90 pickManagedSettings', () {
    test('precedence, distinct keys, falsy, undefined hole, fresh bag', () {
      final e = _map(t['pick']);
      final T = cms.COPILOT_TEMPORARY_ALLOW_LOCAL_HARNESS_KEY;
      final prec = _list(e['precedence']);
      expect(cms.pickManagedSettings(<String, Object?>{T: false}, <String, Object?>{T: true}, <String, Object?>{T: true}).values, _map(prec[0]));
      expect(cms.pickManagedSettings(<String, Object?>{}, <String, Object?>{T: false}, <String, Object?>{T: true}).values, _map(prec[1]));
      expect(cms.pickManagedSettings(<String, Object?>{}, <String, Object?>{}, <String, Object?>{T: true}).values, _map(prec[2]));

      final distinct = _map(e['distinctKeys']);
      final dp = cms.pickManagedSettings(
        <String, Object?>{'shared': 'native', 'nativeOnly': 'n'},
        <String, Object?>{'shared': 'server', 'serverOnly': 's'},
        <String, Object?>{'shared': 'file', 'fileOnly': 'f'},
      );
      expect(dp.values, _map(distinct['values']));
      expect(dp.activeSources, distinct['activeSources']);

      final falsy = _map(e['falsy']);
      expect(cms.pickManagedSettings(
        <String, Object?>{'flag': false, 'count': 0, 'name': ''}, null,
        <String, Object?>{'flag': true, 'count': 99, 'name': 'lower'}).values, _map(falsy['values']));

      final hole = _map(e['undefinedHole']);
      expect(cms.pickManagedSettings(
        <String, Object?>{'a': null, 'b': 'native'},
        <String, Object?>{'a': 'server'}, null).values, _map(hole['values']));

      final native = <String, Object?>{'a': 'native'};
      expect(identical(cms.pickManagedSettings(native, null, null).values, native), !(e['freshObject'] as bool));
    });

    test('force-on-wins, deny-wins, activeSources & provenance match truth', () {
      final e = _map(t['pick']);
      Object? encPick(cms.IManagedSettingsPick p) => <String, Object?>{
        'values': p.values,
        'resolutions': p.resolutions.entries.map((r) => <Object?>[
          r.key,
          <String, Object?>{
            'value': r.value.value,
            'source': r.value.source,
