      final forceOn = _map(_map(e['forceOn'])['nativeFalseServerTrue']);
      final S = cms.COPILOT_SANDBOX_ENABLED_KEY;
      expect(encPick(cms.pickManagedSettings(
        <String, Object?>{S: false}, <String, Object?>{S: true}, <String, Object?>{S: true})), forceOn);

      final deny = _map(e['denyWins']);
      final B = cms.COPILOT_SANDBOX_ALLOW_BYPASS_KEY;
      expect(encPick(cms.pickManagedSettings(
        <String, Object?>{B: true}, <String, Object?>{B: false}, <String, Object?>{B: true})), deny);

      final allU = _map(_map(e['forceOn'])['allUndefined']);
      expect(encPick(cms.pickManagedSettings(null, null, null)), allU);
      final allE = _map(_map(e['forceOn'])['allEmpty']);
      expect(encPick(cms.pickManagedSettings(<String, Object?>{}, <String, Object?>{}, <String, Object?>{})), allE);

      final flat = _map(e['flatNative']);
      final I = cms.COPILOT_OTEL_CAPTURE_IDENTITY_KEY;
      expect(encPick(cms.pickManagedSettings(
        <String, Object?>{I: false},
        <String, Object?>{I: true, 'telemetry.enabled': true}, null)), flat);

      final absent = _map(e['absentTelemetry']);
      final file = cms.normalizeManagedSettings(<String, Object?>{
        'telemetry': <String, Object?>{'capture': <String, Object?>{'identity': true}}});
      expect(encPick(cms.pickManagedSettings(
        <String, Object?>{'model': 'native', S: false},
        <String, Object?>{'model': 'server', 'serverOnly': true},
        <String, Object?>{...file, 'fileOnly': true, S: true})), absent);

      final comm = _map(e['communication']);
      final C = cms.COPILOT_COMMUNICATION_SUPPORT_URL_KEY;
      expect(cms.normalizeManagedSettings(<String, Object?>{
        'communication': <String, Object?>{'support': <String, Object?>{'url': 'https://file.example/help'}}}), _map(comm['file']));
      expect(cms.pickManagedSettings(null,
        cms.normalizeManagedSettings(<String, Object?>{
          'communication': <String, Object?>{'support': <String, Object?>{'url': 'https://server.example/help'}}}),
        cms.normalizeManagedSettings(<String, Object?>{
          'communication': <String, Object?>{'support': <String, Object?>{'url': 'https://file.example/help'}}})).values, _map(comm['server']));
      expect(cms.pickManagedSettings(<String, Object?>{C: 'https://mdm.example/help'}, null,
        cms.normalizeManagedSettings(<String, Object?>{
          'communication': <String, Object?>{'support': <String, Object?>{'url': 'https://file.example/help'}}})).values, _map(comm['native']));
      expect(cms.normalizeManagedSettings(<String, Object?>{'communication': 'https://scalar.example'}), _map(comm['scalar']));
    });
